-- A pattern's program, or NULL when the pattern is no Appendix F regular expression. The pattern is read twice:
-- escapes into tokens (an escape reads the same inside and outside a class, so its extent never depends on where the
-- reader stands), then the tokens by Appendix F's productions, into code over a list of classes.
--
-- The program is the code, comma-separated, then each class's multirange, each after a ';'. Each instruction:
--   0 len         nothing (a slot the group did not need), len ints long
--   1 k           one character of class k
--   2 off  3  4   alternatives: begin (its end off ints on), between two, end
--   5 m n off     repeat the code up to its end (off ints on) m to n times, n -1 unbounded
--   6 off         the end of a repeat (its begin off ints back)
--   7 k m n       a run of m to n characters of class k (n -1 unbounded)
-- A count is read by its digits; one past 2147483647 is that number, which no value reaches (a text holds fewer
-- characters), so it means the same: a repetition stops by its set long before.
create function p3.xsd_compile(p text) returns text language plpgsql immutable as $f$
declare
  ch text[];                  -- the pattern's characters
  cp int[];                   -- their code points
  n int;
  -- tokens: a character as written (plain), a character escape (its code point), or a class escape (its set)
  tp boolean[] := '{}';
  tc int[] := '{}';
  ts int4multirange[] := '{}';
  tpos int[] := '{}';         -- each token's first character
  nt int := 0;
  u int4multirange := '{[9,11),[13,14),[32,55296),[57344,65534),[65536,1114112)}';   -- XML's Char, the alphabet
  i int := 1;
  t int;
  c int;
  l int;
  j int;
  prop text;
  setv int4multirange;
  code int[] := '{0,2}';      -- the whole pattern's alternatives slot
  classes text[] := '{}';
  -- groups: frame 1 is the whole pattern; each frame's slot (a group's repeat slot, 4 ints, then its alternatives
  -- slot, 2 ints) and whether it holds a |
  g_slot int[] := array[1];
  g_alt boolean[] := array[false];
  g_count int[] := array[0];         -- pieces in the frame's branch being read
  g_cls int[] := array[0];           -- that branch's class when it is one class taken once alone, else 0
  g_last int[] := array[0];          -- that branch's repeat instruction when it is one repeat alone, else 0
  g_union text[] := array[null]::text[];   -- the union of the frame's branches so far, each one class alone
  g_unionok boolean[] := array[true];
  gd int := 1;
  -- classes: the open class and each class it subtracts from
  k int;
  c_neg boolean[];
  c_mem int4multirange[];
  c_cnt int[];
  opening boolean;
  fc int;
  lc int;
  -- the atom just read: a class, or a group at its slot; its class when it is one class alone, and the group's repeat
  -- instruction when it is one repeat alone
  a_slot int;
  a_cls int;
  a_rep int;
  -- the piece emitted: whether any code, its repeat instruction, its class when taken once
  emitted boolean;
  last int;
  is_cls int;
  -- its count
  written boolean;
  lo int;
  hi int;
  lo_s text;
  hi_s text;
  d0 int;
  d1 int;
  m0 int;
  m1 int;
  e int;
begin
  if p is null then return null; end if;
  ch := string_to_array(p, null);
  n := coalesce(cardinality(ch), 0);
  cp := array(select ascii(pc) from unnest(ch) with ordinality as q(pc, o) order by o);
  -- Escapes into tokens.
  while i <= n loop
    c := cp[i];
    nt := nt + 1;
    tpos[nt] := i;
    if c <> 92 then
      tp[nt] := true; tc[nt] := c; i := i + 1;
    else
      if i = n then return null; end if;
      l := cp[i + 1];
      tp[nt] := false;
      if l = 110 then tc[nt] := 10; i := i + 2;
      elsif l = 114 then tc[nt] := 13; i := i + 2;
      elsif l = 116 then tc[nt] := 9; i := i + 2;
      elsif l in (92, 124, 46, 63, 42, 43, 40, 41, 123, 125, 45, 91, 93, 94) then tc[nt] := l; i := i + 2;
      elsif l in (115, 105, 99, 100, 119) then ts[nt] := xsd_escape_set(letter => chr(l))::int4multirange; i := i + 2;
      elsif l in (83, 73, 67, 68, 87) then ts[nt] := u - xsd_escape_set(letter => chr(l + 32))::int4multirange; i := i + 2;
      elsif l in (112, 80) then
        if i + 3 > n or cp[i + 2] <> 123 then return null; end if;
        j := array_position(cp, 125, i + 3);
        if j is null then return null; end if;
        prop := xsd_property_set(name => array_to_string(ch[i + 3:j - 1], ''));
        if prop is null then return null; end if;
        ts[nt] := case when l = 80 then u - prop::int4multirange else prop::int4multirange end;
        i := j + 1;
      else
        return null;
      end if;
    end if;
  end loop;
  -- Tokens by Appendix F. Code is only ever appended or overwritten in place, never sliced: a group the reading
  -- simplifies keeps its place as no-ops, so a pattern of any nesting compiles in time linear in its length.
  t := 1;
  while t <= nt loop
    c := case when tp[t] then tc[t] end;
    a_cls := 0; a_rep := 0; a_slot := null;
    if c = 124 then
      if g_count[gd] = 1 and g_cls[gd] > 0 and g_unionok[gd] then
        g_union[gd] := (coalesce(g_union[gd], '{}')::int4multirange + classes[g_cls[gd]]::int4multirange)::text;
      else
        g_unionok[gd] := false;
      end if;
      code := code || 3;
      g_alt[gd] := true; g_count[gd] := 0; g_cls[gd] := 0; g_last[gd] := 0;
      t := t + 1;
      continue;
    elsif c = 40 then
      if t < nt and tp[t + 1] and tc[t + 1] = 63 then return null; end if;
      gd := gd + 1;
      g_slot[gd] := cardinality(code) + 1; g_alt[gd] := false; g_count[gd] := 0; g_cls[gd] := 0; g_last[gd] := 0;
      g_union[gd] := null; g_unionok[gd] := true;
      code := code || 0; code := code || 4; code := code || 0; code := code || 0; code := code || 0; code := code || 2;
      t := t + 1;
      continue;
    elsif c = 41 then
      if gd = 1 then return null; end if;
      a_slot := g_slot[gd];
      if g_alt[gd] then
        code := code || 4;
        code[a_slot + 4] := 2; code[a_slot + 5] := cardinality(code) - (a_slot + 4);
        if g_count[gd] = 1 and g_cls[gd] > 0 and g_unionok[gd] then
          -- Alternatives that are each one class alone are their union, one class: (a|b) is [ab].
          prop := (coalesce(g_union[gd], '{}')::int4multirange + classes[g_cls[gd]]::int4multirange)::text;
          a_cls := array_position(classes, prop);
          if a_cls is null then
            classes := classes || prop; a_cls := cardinality(classes);
          end if;
          code[a_slot + 4] := 1; code[a_slot + 5] := a_cls;
          code[a_slot + 6] := 0; code[a_slot + 7] := cardinality(code) - (a_slot + 6) + 1;
        end if;
      elsif g_count[gd] = 1 then
        a_cls := g_cls[gd]; a_rep := g_last[gd];
      end if;
      gd := gd - 1;
      t := t + 1;
    elsif c in (63, 42, 43, 123, 125, 93) then
      return null;
    else
      if c = 91 then
        -- A class: its frames, each subtracting the one inside it, read until the outermost closes.
        k := 0; c_neg := '{}'; c_mem := '{}'; c_cnt := '{}';
        loop
          k := k + 1; t := t + 1;
          c_neg[k] := t <= nt and tp[t] and tc[t] = 94;
          if c_neg[k] then t := t + 1; end if;
          c_mem[k] := '{}'; c_cnt[k] := 0; opening := false;
          loop
            if t > nt then return null; end if;
            if tp[t] and tc[t] = 93 then
              if c_cnt[k] = 0 then return null; end if;
              exit;
            elsif tp[t] and tc[t] = 91 then
              return null;
            elsif tp[t] and tc[t] = 45 then
              if t < nt and tp[t + 1] and tc[t + 1] = 91 then
                if c_cnt[k] = 0 then return null; end if;
                t := t + 1; opening := true;
                exit;
              end if;
              if c_cnt[k] > 0 and not (t < nt and tp[t + 1] and tc[t + 1] = 93) then return null; end if;
              c_mem[k] := c_mem[k] + '{[45,46)}'; c_cnt[k] := c_cnt[k] + 1; t := t + 1;
            elsif tc[t] is null then
              c_mem[k] := c_mem[k] + ts[t]; c_cnt[k] := c_cnt[k] + 1; t := t + 1;
            else
              fc := tc[t]; t := t + 1;
              if t < nt and tp[t] and tc[t] = 45 and not (tp[t + 1] and tc[t + 1] in (93, 91)) then
                if tp[t + 1] and tc[t + 1] = 45 then return null; end if;
                t := t + 1;
                lc := tc[t];
                if lc is null or lc < fc then return null; end if;
                t := t + 1;
              else
                lc := fc;
              end if;
              c_mem[k] := c_mem[k] + int4multirange(int4range(fc, lc, '[]')); c_cnt[k] := c_cnt[k] + 1;
            end if;
          end loop;
          exit when not opening;
        end loop;
        setv := case when c_neg[k] then u - c_mem[k] else c_mem[k] end;
        t := t + 1; k := k - 1;
        while k > 0 loop
          if t > nt or not (tp[t] and tc[t] = 93) then return null; end if;
          setv := case when c_neg[k] then u - c_mem[k] else c_mem[k] end - setv;
          t := t + 1; k := k - 1;
        end loop;
      elsif c = 46 then
        setv := xsd_escape_set(letter => '.')::int4multirange; t := t + 1;
      elsif tc[t] is null then
        setv := ts[t]; t := t + 1;
      else
        setv := int4multirange(int4range(tc[t], tc[t], '[]')); t := t + 1;
      end if;
      prop := (setv * u)::text;
      a_cls := array_position(classes, prop);
      if a_cls is null then
        classes := classes || prop; a_cls := cardinality(classes);
      end if;
    end if;
    -- The atom's count, by its digits: n <= m is Appendix F's (production [3]), compared as written.
    written := false; lo := 1; hi := 1;
    c := case when t <= nt and tp[t] then tc[t] end;
    if c = 63 then written := true; lo := 0; hi := 1; t := t + 1;
    elsif c = 42 then written := true; lo := 0; hi := -1; t := t + 1;
    elsif c = 43 then written := true; lo := 1; hi := -1; t := t + 1;
    elsif c = 123 then
      d0 := t + 1; d1 := d0;
      while d1 <= nt and tp[d1] and tc[d1] between 48 and 57 loop d1 := d1 + 1; end loop;
      if d1 = d0 or d1 > nt or not tp[d1] then return null; end if;
      if tc[d1] = 44 then
        m0 := d1 + 1; m1 := m0;
        while m1 <= nt and tp[m1] and tc[m1] between 48 and 57 loop m1 := m1 + 1; end loop;
        j := m1;
      else
        m0 := null; m1 := null; j := d1;
      end if;
      if j > nt or not tp[j] or tc[j] <> 125 then return null; end if;
      lo_s := ltrim(array_to_string(ch[tpos[d0]:tpos[d1 - 1]], ''), '0');
      if m0 is null then
        hi_s := lo_s;
      elsif m1 = m0 then
        hi_s := null;
      else
        hi_s := ltrim(array_to_string(ch[tpos[m0]:tpos[m1 - 1]], ''), '0');
        if length(lo_s) > length(hi_s) or (length(lo_s) = length(hi_s) and lo_s > hi_s) then return null; end if;
      end if;
      lo := case when length(lo_s) > 10 then 2147483647 else least(coalesce(nullif(lo_s, '')::bigint, 0), 2147483647) end;
      hi := case when hi_s is null then -1 when length(hi_s) > 10 then 2147483647
        else least(coalesce(nullif(hi_s, '')::bigint, 0), 2147483647) end;
      written := true; t := j + 1;
    end if;
    if written and t <= nt and tp[t] and tc[t] in (63, 43, 42, 123) then return null; end if;
    -- The piece's code: a class once or as a run; a group inline, as a run when it holds one class alone, folded into
    -- the one repeat it holds alone, or repeated; a count of zero (the empty string alone) as nothing.
    emitted := true; last := 0; is_cls := 0;
    if a_slot is null then
      if lo = 1 and hi = 1 then
        code := code || 1; code := code || a_cls;
        is_cls := a_cls;
      elsif hi <> 0 then
        last := cardinality(code) + 1;
        code := code || 7; code := code || a_cls; code := code || lo; code := code || hi;
      else
        emitted := false;
      end if;
    elsif lo = 1 and hi = 1 then
      is_cls := a_cls; last := a_rep;
    elsif hi = 0 then
      code[a_slot] := 0; code[a_slot + 1] := cardinality(code) - a_slot + 1;
      emitted := false;
    elsif a_cls > 0 then
      code[a_slot] := 7; code[a_slot + 1] := a_cls; code[a_slot + 2] := lo; code[a_slot + 3] := hi;
      code[a_slot + 4] := 0; code[a_slot + 5] := cardinality(code) - (a_slot + 4) + 1;
      last := a_slot;
    elsif a_rep > 0 and ((code[a_rep + case when code[a_rep] = 7 then 3 else 2 end] = -1
        and code[a_rep + case when code[a_rep] = 7 then 2 else 1 end] in (0, 1))
        or (code[a_rep + case when code[a_rep] = 7 then 2 else 1 end] = 0
        and code[a_rep + case when code[a_rep] = 7 then 3 else 2 end] = 1)) then
      -- The group holds one repeat alone, of S, whose count folds into this one exactly: (S*){m,n} = S*,
      -- (S+){m,n} = S{m,}, (S?){m,n} = S{0,n} (n is at least 1 here). So repeats nested many levels deep take one
      -- level's work.
      e := a_rep + case when code[a_rep] = 7 then 2 else 1 end;
      if code[e + 1] = -1 and code[e] = 0 then
        lo := 0; hi := -1;
      elsif code[e + 1] = -1 then
        hi := -1;
      else
        lo := 0;
      end if;
      code[e] := lo; code[e + 1] := hi;
      last := a_rep;
    else
      code := code || 6; code := code || 0;
      e := cardinality(code) - 1;
      code[a_slot] := 5; code[a_slot + 1] := lo; code[a_slot + 2] := hi; code[a_slot + 3] := e - a_slot;
      code[e + 1] := e - a_slot;
      last := a_slot;
    end if;
    if emitted then
      g_count[gd] := g_count[gd] + 1;
      g_cls[gd] := case when g_count[gd] = 1 then is_cls else 0 end;
      g_last[gd] := case when g_count[gd] = 1 then last else 0 end;
    end if;
  end loop;
  if gd > 1 then return null; end if;
  if g_alt[1] then
    code := code || 4;
    code[1] := 2; code[2] := cardinality(code) - 1;
  end if;
  return array_to_string(code, ',') || case when cardinality(classes) > 0 then ';' || array_to_string(classes, ';') else '' end;
end $f$;

-- The one interpreter of a compiled pattern over a value, in three modes. 'whole' (start 0): whether the whole value
-- is in the language, 1 or 0 (xsd_run). 'end': the end of the match XPath and XQuery Functions and Operators 3.1
-- chooses starting exactly at position start (fn:tokenize, fn:replace: "If two alternatives within the pattern both
-- match at the same position in the $input, then the match that is chosen is the first"; quantifiers greedy), or
-- NULL where no match starts there (xsd_match_end). 'scan': every separator fn:tokenize finds, left to right without
-- overlap from start, each the match chosen at the leftmost position where one begins, as start,end pairs
-- (xsd_separators); the walk takes each from the program's feasible-start set, read once.
--
-- It reads backward. A code range maps the set of positions where its match may end to the set where it may begin
-- (bit p of each set is position p): a class takes the positions one before the set that hold one of its characters;
-- a sequence reads its pieces last to first; alternatives are the union of their branches; a repetition S{m,n} reads
-- S on the set again and again, below m stepping it, from m growing it (T := T | S(T), S distributing over union),
-- stopping on an empty or unchanged set, at n, or when a round adds nothing: within |value| + 2 rounds whatever m and
-- n are. A run of one class reads by doubling, in O(log² |value|) set operations. A whole match is position 0 of the
-- program read back from {|value|}.
--
-- The walk follows the priority path, choosing at each alternative, each repeat's iterate-or-stop and each run of a
-- class the first option (in the pattern's order, more iterations before fewer) whose rest can match: whose position
-- lies in that decision's feasible-start set, the rest of the program, through the frames the walk holds (an
-- alternative going on after its end, a repeat through its remaining iterations), read back from every position. A
-- set is read once per decision context and kept, so a match end costs a reading per context it meets, not one per
-- decision. An iteration begun at its minimum or past it may not end where it began (ECMAScript's RepeatMatcher, the
-- rule of Perl's engines): when the walk decides at such a start, that start is left out of the iteration's end set,
-- the one reading not kept (it holds the walk's position). Empty iterations below the minimum, while more counts are
-- left than the value is long, repeat one path, so the walk takes them at once.
create function p3.xsd_walk(mode text, program text, start integer, v text) returns text language plpgsql immutable as $f$
declare
  parts text[];
  code int[];
  nc int;
  cps int[];
  len int;
  zero varbit;
  everywhere varbit;
  pows varbit[] := '{}';      -- class k's positions starting a run of 2^b of its characters, at (k - 1) * 32 + b + 1
  cls int4multirange;
  base int;
  -- the program's sequences: each unit's previous unit in its sequence (0 for the first) and the marker that ends its
  -- sequence (an alternative's | or end, a repeat's end, or nc + 1 for the whole program's); each marker's sequence's
  -- last unit (0 for none); each alternatives' first marker, and each | its next
  prevu int[] := '{}';
  seqend int[] := '{}';
  seqlast int[] := '{}';
  altfirst int[] := '{}';
  altnext int[] := '{}';
  toplast int;
  s_last int[] := '{}';
  s_alt int[] := '{}';
  s_mark int[] := '{}';
  d int;
  u int;
  i int;
  op int;
  -- the backward reader's stack: 1 a sequence (the unit it reads next, the unit it stops before, its set); 2
  -- alternatives (the unit, the set after it, the marker ending the branch being read, the union so far); 3 a
  -- repetition (the unit, its counts, the iterations read, the set its body was last read from)
  esp int := 0;
  e_kind int[] := '{}';
  e_u int[] := '{}';
  e_stop int[] := '{}';
  e_set varbit[] := '{}';
  e_m int[] := '{}';
  e_n int[] := '{}';
  e_k int[] := '{}';
  e_prev varbit[] := '{}';
  e_mk int[] := '{}';
  e_acc varbit[] := '{}';
  ret varbit;
  -- feasible-start sets kept, by context; the context being read (its frame, its phase, its key, its set, the walk's
  -- position its repeats' ends leave out, or -1)
  c_key text[] := '{}';
  c_set varbit[] := '{}';
  ch_j int;
  ch_phase int;
  ch_key text;
  ch_keep boolean;
  ch_xp int;
  ch_pc int;
  cx int;
  tset varbit;
  g varbit;
  -- the walk: its instruction, position and frames (2: an alternative taken; 5: a repeat in an iteration: its counts,
  -- iterations done, body, and where the iteration began), and the choice its next set decides (4 a match at all, 1
  -- the alternative at w_try, 2 one more iteration, 3 a run of the class, 0 none)
  wpc int := 1;
  wp int;
  wsp int := 0;
  w_kind int[] := '{}';
  w_start int[] := '{}';
  w_end int[] := '{}';
  w_m int[] := '{}';
  w_n int[] := '{}';
  w_k int[] := '{}';
  w_body int[] := '{}';
  w_iter int[] := '{}';
  pending int;
  w_try int;
  w_lo int;
  w_hi int;
  w_x int;
  m2 int;
  n2 int;
  -- a run's work: its set, the step it takes, its reach
  run varbit;
  stepped varbit;
  j int;
  jj int;
  b int;
  s int;
  reach int;
  covered int;
  m int;
  nn int;
  -- a scan: the separators so far, where the next search begins, where the match being walked began, and the
  -- program's feasible-start set (where a match begins) as text
  scan_out text := '';
  scan_pos int;
  scan_s int;
  g0 text;
begin
  if program is null or v is null or start is null then return null; end if;
  parts := string_to_array(program, ';');
  code := case when parts[1] = '' then '{}'::int[] else string_to_array(parts[1], ',')::int[] end;
  nc := coalesce(cardinality(code), 0);
  cps := array(select ascii(vc) from unnest(string_to_array(v, null)) with ordinality as q(vc, o) order by o);
  len := coalesce(cardinality(cps), 0);
  if start < 0 or start > len then return null; end if;
  zero := repeat('0', len + 1)::varbit;
  everywhere := repeat('1', len + 1)::varbit;
  -- Every array indexed by instruction or class at its full size at once: an assignment below an array's lower bound
  -- moves every element, so a sequence's units, assigned last to first, would cost the square of its length.
  prevu := array_fill(0, array[nc + 1]); seqend := array_fill(0, array[nc + 1]); seqlast := array_fill(0, array[nc + 1]);
  altfirst := array_fill(0, array[nc + 1]); altnext := array_fill(0, array[nc + 1]);
  pows := array_fill(null::varbit, array[32 * greatest(cardinality(parts) - 1, 1)]);
  -- The program's sequences, in one scan: a unit is an instruction outside every marker, an alternatives or a
  -- repetition whole; a no-op whole, with whatever code it covers.
  d := 1; s_last[1] := 0; i := 1;
  while i <= nc loop
    op := code[i];
    if op in (3, 4, 6) then
      seqlast[i] := s_last[d];
      u := s_last[d];
      while u > 0 loop seqend[u] := i; u := prevu[u]; end loop;
      if op = 6 then
        d := d - 1; i := i + 2;
      else
        if s_mark[d] = 0 then altfirst[s_alt[d]] := i; else altnext[s_mark[d]] := i; end if;
        s_mark[d] := i; altnext[i] := 0;
        if op = 3 then s_last[d] := 0; else d := d - 1; end if;
        i := i + 1;
      end if;
    else
      prevu[i] := s_last[d]; s_last[d] := i;
      if op = 2 then
        d := d + 1; s_last[d] := 0; s_alt[d] := i; s_mark[d] := 0; i := i + 2;
      elsif op = 5 then
        d := d + 1; s_last[d] := 0; i := i + 4;
      elsif op = 0 then
        i := i + code[i + 1];
      elsif op = 1 then
        i := i + 2;
      else
        i := i + 4;
      end if;
    end if;
  end loop;
  toplast := s_last[1];
  u := toplast;
  while u > 0 loop seqend[u] := nc + 1; u := prevu[u]; end loop;
  if mode = 'whole' then
    esp := 1; e_kind[1] := 1; e_u[1] := toplast; e_stop[1] := 0; e_set[1] := set_bit(zero, len, 1);
    pending := 5;
  else
    wp := start;
    pending := case when mode = 'scan' then 6 else 4 end;
    ch_pc := 1; ch_xp := -1; ch_j := 1; ch_phase := 1; ch_key := 't'; ch_keep := true; tset := everywhere;
  end if;
  <<main>> loop
    -- A backward reading in progress: read it to its end, its set in ret.
    while esp > 0 loop
      u := e_u[esp];
      if e_kind[esp] = 1 and u <> 0 and u <> e_stop[esp] and bit_count(e_set[esp]) > 0 then
        op := code[u];
        if op = 0 then
          e_u[esp] := prevu[u];
        elsif op = 1 or op = 7 then
          base := (code[u + 1] - 1) * 32;
          if pows[base + 1] is null then
            cls := parts[code[u + 1] + 1]::int4multirange;
            pows[base + 1] := (coalesce((select string_agg(case when vc <@ cls then '1' else '0' end, '' order by o)
              from unnest(cps) with ordinality as q(vc, o)), '') || '0')::varbit;
          end if;
          if op = 1 then
            e_set[esp] := (e_set[esp] << 1) & pows[base + 1];
          else
            -- A run of m to n characters of the class, backward: the set stepped back m characters, then the union
            -- of every further step back up to n (or the value's length), each round doubling what it covers.
            m := code[u + 2]; nn := code[u + 3];
            if m > len then
              e_set[esp] := zero;
            else
              reach := case when nn < 0 or nn > len then len - m else nn - m end;
              run := e_set[esp]; covered := -1;
              loop
                if covered < 0 then
                  j := m;
                else
                  exit when covered >= reach;
                  j := least(covered + 1, reach - covered);
                end if;
                -- stepped := the set stepped back j characters of the class: a step of 2^b per bit b of j
                stepped := run; jj := j; b := 0; s := 1;
                while jj > 0 and bit_count(stepped) > 0 loop
                  if b > 0 and pows[base + b + 1] is null then
                    pows[base + b + 1] := pows[base + b] & (pows[base + b] << (s / 2));
                  end if;
                  if jj % 2 = 1 then
                    stepped := (stepped << s) & pows[base + b + 1];
                  end if;
                  jj := jj / 2; b := b + 1;
                  if jj > 0 and s >= len then
                    stepped := zero;
                    exit;
                  end if;
                  s := s * 2;
                end loop;
                if covered < 0 then
                  run := stepped; covered := 0;
                  exit when bit_count(run) = 0;
                else
                  exit when bit_count(stepped) = 0;
                  run := run | stepped; covered := covered + j;
                end if;
              end loop;
              e_set[esp] := run;
            end if;
          end if;
          e_u[esp] := prevu[u];
        elsif op = 2 then
          esp := esp + 1;
          e_kind[esp] := 2; e_u[esp] := u; e_set[esp] := e_set[esp - 1]; e_mk[esp] := altfirst[u]; e_acc[esp] := zero;
          esp := esp + 1;
          e_kind[esp] := 1; e_u[esp] := seqlast[e_mk[esp - 1]]; e_stop[esp] := 0; e_set[esp] := e_set[esp - 1];
        else
          esp := esp + 1;
          e_kind[esp] := 3; e_u[esp] := u; e_m[esp] := code[u + 1]; e_n[esp] := code[u + 2]; e_k[esp] := 0;
          e_prev[esp] := e_set[esp - 1];
          esp := esp + 1;
          e_kind[esp] := 1; e_u[esp] := seqlast[u + code[u + 3]]; e_stop[esp] := 0; e_set[esp] := e_prev[esp - 1];
        end if;
      else
        -- A sequence read to its end, or a repetition about to begin: deliver its set to what holds it.
        if e_kind[esp] = 1 then
          ret := e_set[esp]; esp := esp - 1;
        else
          -- a repetition at the stack's base (a frame's remaining iterations): read its body first
          esp := esp + 1;
          e_kind[esp] := 1; e_u[esp] := seqlast[e_u[esp - 1] + code[e_u[esp - 1] + 3]]; e_stop[esp] := 0;
          e_set[esp] := e_prev[esp - 1];
          continue;
        end if;
        loop
          exit when esp = 0;
          if e_kind[esp] = 2 then
            e_acc[esp] := e_acc[esp] | ret;
            e_mk[esp] := altnext[e_mk[esp]];
            if e_mk[esp] = 0 then
              ret := e_acc[esp]; esp := esp - 1;
            else
              esp := esp + 1;
              e_kind[esp] := 1; e_u[esp] := seqlast[e_mk[esp - 1]]; e_stop[esp] := 0; e_set[esp] := e_set[esp - 1];
              exit;
            end if;
          elsif e_kind[esp] = 3 then
            -- ret is the body read from e_prev: below m step the set, from m grow it; stop as the reading says
            if e_k[esp] < e_m[esp] then
              e_k[esp] := e_k[esp] + 1;
              if bit_count(ret) = 0 or ret = e_prev[esp] or (e_k[esp] = e_m[esp] and e_n[esp] = e_m[esp]) then
                esp := esp - 1;
                continue;
              end if;
              e_prev[esp] := ret;
            else
              ret := e_prev[esp] | ret;
              e_k[esp] := e_k[esp] + 1;
              if ret = e_prev[esp] or (e_n[esp] >= 0 and e_k[esp] >= e_n[esp]) then
                esp := esp - 1;
                continue;
              end if;
              e_prev[esp] := ret;
            end if;
            esp := esp + 1;
            e_kind[esp] := 1; e_u[esp] := seqlast[e_u[esp - 1] + code[e_u[esp - 1] + 3]]; e_stop[esp] := 0;
            e_set[esp] := ret;
            exit;
          else
            e_set[esp] := ret; e_u[esp] := prevu[e_u[esp]];
            exit;
          end if;
        end loop;
      end if;
    end loop;
    if pending = 5 then return get_bit(ret, 0)::text; end if;
    -- A decision's feasible-start set, context by context: the range after each frame's unit to its sequence's end,
    -- then that frame's remaining iterations (a repeat's), outermost first; then the range from ch_pc on.
    if ch_phase > 0 then
      if ch_phase = 2 or ch_phase = 4 or ch_phase = 6 then
        -- a reading just ended: its set
        tset := ret;
        if ch_keep then c_key := c_key || ch_key; c_set := c_set || tset; end if;
        ch_phase := ch_phase - 1;
        if ch_phase = 1 then ch_phase := 3; elsif ch_phase = 3 then ch_phase := 7; elsif ch_phase = 5 then ch_phase := 8; end if;
      end if;
      if ch_phase = 1 then
        if ch_j > wsp then
          ch_phase := 5;
        else
          ch_key := ch_key || '|a' || w_start[ch_j];
          cx := case when ch_keep then array_position(c_key, ch_key) end;
          if cx is not null then
            tset := c_set[cx]; ch_phase := 3;
          else
            u := seqend[w_start[ch_j]];
            esp := 1; e_kind[1] := 1; e_u[1] := case when u = nc + 1 then toplast else seqlast[u] end;
            e_stop[1] := w_start[ch_j]; e_set[1] := tset;
            ch_phase := 2;
            continue main;
          end if;
        end if;
      end if;
      if ch_phase = 3 then
        -- the frame's end: an alternative goes on after its end; a repeat through its remaining iterations
        if w_kind[ch_j] = 5 then
          m2 := greatest(w_m[ch_j] - w_k[ch_j] - 1, 0);
          n2 := case when w_n[ch_j] < 0 then -1 else w_n[ch_j] - w_k[ch_j] - 1 end;
          if m2 > len + 2 then m2 := len + 2; n2 := -1; elsif n2 >= 0 and n2 - m2 >= len + 2 then n2 := -1; end if;
          ch_key := ch_key || '|r' || m2 || ',' || n2;
          if n2 <> 0 then
            cx := case when ch_keep then array_position(c_key, ch_key) end;
            if cx is not null then
              tset := c_set[cx];
            else
              esp := 1; e_kind[1] := 3; e_u[1] := w_start[ch_j]; e_m[1] := m2; e_n[1] := n2; e_k[1] := 0;
              e_prev[1] := tset;
              ch_phase := 4;
              continue main;
            end if;
          end if;
        end if;
        ch_phase := 7;
      end if;
      if ch_phase = 7 then
        if ch_xp >= 0 and w_kind[ch_j] = 5 and w_k[ch_j] >= w_m[ch_j] and w_iter[ch_j] = ch_xp then
          tset := set_bit(tset, ch_xp, 0); ch_keep := false;
        end if;
        ch_j := ch_j + 1; ch_phase := 1;
        continue main;
      end if;
      if ch_phase = 5 then
        ch_key := ch_key || '|g' || ch_pc;
        cx := case when ch_keep then array_position(c_key, ch_key) end;
        if cx is not null then
          tset := c_set[cx];
        elsif not (ch_pc > nc or code[ch_pc] in (3, 4, 6)) then
          u := seqend[ch_pc];
          esp := 1; e_kind[1] := 1; e_u[1] := case when u = nc + 1 then toplast else seqlast[u] end;
          e_stop[1] := prevu[ch_pc]; e_set[1] := tset;
          ch_phase := 6;
          continue main;
        end if;
        ch_phase := 8;
      end if;
      -- ch_phase = 8: the set is read
      g := tset; ch_phase := 0;
      -- The walk's choice the set decides.
      if pending = 4 then
        if get_bit(g, wp) = 0 then return null; end if;
        pending := 0;
      elsif pending = 6 then
        -- a scan: where a match begins, kept as text; the first search from start
        g0 := g::text; scan_pos := start; pending := 7;
      elsif pending = 1 then
        if get_bit(g, wp) = 1 then
          pending := 0; wpc := w_try;
        else
          -- the next alternative: after the next | of these alternatives
          i := w_try;
          if not (i <= nc and code[i] in (3, 4)) then i := seqend[i]; end if;
          if code[i] = 4 then raise exception 'xsd_walk: no alternative is feasible at %', wp using errcode = 'XX000'; end if;
          w_try := i + 1;
          ch_pc := w_try; ch_j := 1; ch_phase := 1; ch_key := 't'; ch_keep := true; tset := everywhere;
          continue main;
        end if;
      elsif pending = 2 then
        pending := 0;
        if get_bit(g, wp) = 1 then
          wpc := w_body[wsp];
        elsif w_k[wsp] >= w_m[wsp] then
          wpc := w_end[wsp] + 2; wsp := wsp - 1;
        else
          raise exception 'xsd_walk: a required iteration is infeasible at %', wp using errcode = 'XX000';
        end if;
      elsif pending = 3 then
        -- a run: the most characters whose end can go on; one of none (the walk's position) read by itself where
        -- the walk's repeats leave that position out
        if w_x = 0 then
          j := w_hi;
          while j >= greatest(w_lo, 1) and get_bit(g, wp + j) = 0 loop j := j - 1; end loop;
          if j >= greatest(w_lo, 1) then
            pending := 0; wp := wp + j; wpc := wpc + 4;
          elsif w_lo > 0 then
            raise exception 'xsd_walk: no run is feasible at %', wp using errcode = 'XX000';
          else
            -- none: at the walk's position, left out by the repeats that began there, if any
            w_x := 1; ch_xp := -1;
            for i in 1 .. wsp loop
              if w_kind[i] = 5 and w_k[i] >= w_m[i] and w_iter[i] = wp then ch_xp := wp; end if;
            end loop;
            if ch_xp < 0 then
              if get_bit(g, wp) = 0 then raise exception 'xsd_walk: no run is feasible at %', wp using errcode = 'XX000'; end if;
              pending := 0; wpc := wpc + 4;
            else
              ch_pc := wpc + 4; ch_j := 1; ch_phase := 1; ch_key := 't'; ch_keep := true; tset := everywhere;
              continue main;
            end if;
          end if;
        else
          if get_bit(g, wp) = 0 then raise exception 'xsd_walk: no run is feasible at %', wp using errcode = 'XX000'; end if;
          pending := 0; wpc := wpc + 4;
        end if;
      end if;
    end if;
    -- A scan's next separator: the leftmost position at or after scan_pos where a match begins, walked from there.
    if pending = 7 then
      scan_s := case when scan_pos > len then 0 else position('1' in substr(g0, scan_pos + 1)) end;
      if scan_s = 0 then return scan_out; end if;
      scan_s := scan_pos + scan_s - 1;
      wp := scan_s; wpc := 1; wsp := 0; pending := 0;
    end if;
    -- The walk's next step on the priority path.
    if wpc > nc then
      if mode = 'end' then return wp::text; end if;
      -- the separator walked: kept; the next search from its end, or one on where it is empty
      scan_out := scan_out || case when scan_out = '' then '' else ',' end || scan_s || ',' || wp;
      scan_pos := case when wp > scan_s then wp else scan_s + 1 end;
      pending := 7;
      continue main;
    end if;
    op := code[wpc];
    if op = 0 then
      wpc := wpc + code[wpc + 1];
    elsif op = 1 then
      wp := wp + 1; wpc := wpc + 2;
    elsif op = 7 then
      -- A run of the class: as many of its characters as the rest allows, from the most the value holds down.
      base := (code[wpc + 1] - 1) * 32;
      if pows[base + 1] is null then
        cls := parts[code[wpc + 1] + 1]::int4multirange;
        pows[base + 1] := (coalesce((select string_agg(case when vc <@ cls then '1' else '0' end, '' order by o)
          from unnest(cps) with ordinality as q(vc, o)), '') || '0')::varbit;
      end if;
      w_hi := position('0' in substr(pows[base + 1]::text, wp + 1)) - 1;
      if code[wpc + 3] >= 0 and code[wpc + 3] < w_hi then w_hi := code[wpc + 3]; end if;
      w_lo := code[wpc + 2];
      if w_hi < w_lo then raise exception 'xsd_walk: no run is feasible at %', wp using errcode = 'XX000'; end if;
      pending := 3; w_x := 0;
      ch_pc := wpc + 4; ch_xp := -1; ch_j := 1; ch_phase := 1; ch_key := 't'; ch_keep := true; tset := everywhere;
    elsif op = 2 then
      wsp := wsp + 1; w_kind[wsp] := 2; w_start[wsp] := wpc; w_end[wsp] := wpc + code[wpc + 1];
      pending := 1; w_try := wpc + 2;
      ch_xp := -1;
      for i in 1 .. wsp loop
        if w_kind[i] = 5 and w_k[i] >= w_m[i] and w_iter[i] = wp then ch_xp := wp; end if;
      end loop;
      ch_pc := w_try; ch_j := 1; ch_phase := 1; ch_key := 't'; ch_keep := true; tset := everywhere;
    elsif op = 3 then
      wpc := w_end[wsp];
    elsif op = 4 then
      wsp := wsp - 1; wpc := wpc + 1;
    elsif op = 5 then
      wsp := wsp + 1; w_kind[wsp] := 5; w_start[wsp] := wpc; w_m[wsp] := code[wpc + 1]; w_n[wsp] := code[wpc + 2];
      w_k[wsp] := 0; w_body[wsp] := wpc + 4; w_end[wsp] := wpc + code[wpc + 3]; w_iter[wsp] := wp;
      pending := 2;
      ch_xp := -1;
      for i in 1 .. wsp loop
        if w_kind[i] = 5 and w_k[i] >= w_m[i] and w_iter[i] = wp then ch_xp := wp; end if;
      end loop;
      ch_pc := wpc + 4; ch_j := 1; ch_phase := 1; ch_key := 't'; ch_keep := true; tset := everywhere;
    elsif op = 6 then
      w_k[wsp] := w_k[wsp] + 1;
      if wp = w_iter[wsp] and w_k[wsp] < w_m[wsp] - len - 3 then w_k[wsp] := w_m[wsp] - len - 3; end if;
      if w_n[wsp] >= 0 and w_k[wsp] >= w_n[wsp] then
        wsp := wsp - 1; wpc := wpc + 2;
      else
        w_iter[wsp] := wp; pending := 2;
        ch_xp := -1;
        for i in 1 .. wsp loop
          if w_kind[i] = 5 and w_k[i] >= w_m[i] and w_iter[i] = wp then ch_xp := wp; end if;
        end loop;
        ch_pc := w_body[wsp]; ch_j := 1; ch_phase := 1; ch_key := 't'; ch_keep := true; tset := everywhere;
      end if;
    end if;
  end loop;
end $f$;

-- Whether the whole value is in the language of a compiled pattern (QTI 3.0.1 info §5.104: "The result is a single
-- boolean with a value of 'true' if the sub-expression matches the regular expression given by pattern and 'false'
-- if it does not. If the sub-expression is NULL then the operator results in NULL").
create function p3.xsd_run(program text, v text) returns boolean language sql immutable as $f$
  select xsd_walk(mode => 'whole', program => program, start => 0, v => v) = '1'
$f$;

-- The end (exclusive, a code-point offset) of the match F&O 3.1 chooses starting exactly at code-point offset start
-- (0 to the value's length): alternatives in the pattern's order, quantifiers greedy; NULL where none starts there.
-- The match is the value's characters start + 1 to the end, counted from 1.
create function p3.xsd_match_end(program text, start integer, v text) returns integer language sql immutable as $f$
  select xsd_walk(mode => 'end', program => program, start => start, v => v)::integer
$f$;

-- Every separator XPath and XQuery Functions and Operators 3.1's fn:tokenize finds in v, in one reading: left to right
-- and without overlap, each the match chosen at the leftmost position where one begins ("If two alternatives within
-- the pattern both match at the same position in the $input, then the match that is chosen is the first";
-- quantifiers greedy), the next search from its end. As text: start,end pairs, comma-separated, each a code-point
-- offset (start counted from 0, end exclusive, so the separator is v's characters start + 1 to end); '' for none. A
-- match that is empty, which only a pattern that matches the empty string makes (fn:tokenize refuses such a pattern,
-- FORX0003), is kept and steps the next search on by one character.
create function p3.xsd_separators(program text, v text) returns text language sql immutable as $f$
  select xsd_walk(mode => 'scan', program => program, start => 0, v => v)
$f$;

-- qti-pattern-match's value for a pattern known only as it is matched (a variable reference, info §9.3.4
-- StringOrVariableRef): NULL for a NULL pattern or value, and NULL for a pattern that is no Appendix F expression. QTI
-- 3.0.1 gives that case no value; it states an operator's undefined result as NULL throughout (a division by zero, a
-- power or a rounding outside the value set), so an authoring defect in content never aborts a grade (the lead's
-- ruling, 2026-11-20). A literal pattern outside Appendix F is refused at admission and never reaches the machine.
create function p3.xsd_matches(pattern text, v text) returns boolean language sql immutable as $f$
  select xsd_run(program => xsd_compile(p => pattern), v => v)
$f$;
